from itertools import product
def best(a,b):
    # shift b by (dr,dc) to overlap a; returns (matches, missing_in_b, extra_in_b)
    bestt=None
    for dr,dc in product(range(-25,26),range(-25,26)):
        sb={(r+dr,c+dc) for r,c in b}
        m=len(sb & set(a))
        if bestt is None or m>bestt[0]:
            bestt=(m,dr,dc)
    m,dr,dc=bestt
    sb={(r+dr,c+dc) for r,c in b}
    sa=set(a)
    return m,dr,dc, sorted(sa-sb), sorted(sb-sa)
